pub enum OutputMode {
    Color,
    Monochrome,
    Plain,
}

impl OutputMode {
    pub fn detect(no_color: bool) -> Self {
        if no_color || std::env::var("NO_COLOR").is_ok() {
            Self::Monochrome
        } else if atty::is(atty::Stream::Stdout) {
            Self::Color
        } else {
            Self::Plain
        }
    }
}

